{
  "resourceType": "Bundle",
  "type": "collection",
  "entry": [
    {
      "fullUrl": "https://example.org/fhir/Patient/patient-1",
      "resource": {
        "resourceType": "Patient",
        "id": "patient-1",
        "gender": "female"
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Condition/condition-1",
      "resource": {
        "resourceType": "Condition",
        "id": "condition-1",
        "clinicalStatus": {
          "coding": [
            {
              "system": "http://terminology.hl7.org/CodeSystem/condition-clinical",
              "code": "active"
            }
          ]
        },
        "verificationStatus": {
          "coding": [
            {
              "system": "http://terminology.hl7.org/CodeSystem/condition-ver-status",
              "code": "provisional"
            }
          ]
        },
        "code": {
          "text": "Acute mechanical low back pain, likely muscular strain/posture related"
        },
        "subject": {
          "reference": "Patient/patient-1"
        }
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Condition/condition-2",
      "resource": {
        "resourceType": "Condition",
        "id": "condition-2",
        "clinicalStatus": {
          "coding": [
            {
              "system": "http://terminology.hl7.org/CodeSystem/condition-clinical",
              "code": "active"
            }
          ]
        },
        "code": {
          "text": "Depression"
        },
        "subject": {
          "reference": "Patient/patient-1"
        }
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Condition/condition-3",
      "resource": {
        "resourceType": "Condition",
        "id": "condition-3",
        "verificationStatus": {
          "coding": [
            {
              "system": "http://terminology.hl7.org/CodeSystem/condition-ver-status",
              "code": "unconfirmed"
            }
          ]
        },
        "code": {
          "text": "Reported history of periodic limb movements on a sleep study approximately 2 years ago; records unavailable"
        },
        "subject": {
          "reference": "Patient/patient-1"
        }
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-1",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-1",
        "status": "final",
        "code": {
          "text": "Low back pain"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "About 2 weeks, gradual onset, central low lumbar and slightly right-sided; dull ache, sometimes sharp with bending; up to approximately 6–7/10 if pushed, usually described as annoying. Worse after long periods at a desk and lifting shopping. Stiff for the first 10–15 minutes in the morning, then eases. Patient suspects a new office chair or sleeping awkwardly on a couch. Still working part-time and avoiding heavier jobs at home."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-2",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-2",
        "status": "final",
        "code": {
          "text": "Low back pain associated negative symptoms and red flags"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Denies leg pain, pins and needles, weakness, bowel or bladder change, saddle numbness, fevers, weight loss, night sweats, and trauma."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-3",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-3",
        "status": "final",
        "code": {
          "text": "Blood pressure"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "component": [
          {
            "code": {
              "text": "Systolic blood pressure"
            },
            "valueQuantity": {
              "value": 118,
              "unit": "mmHg"
            }
          },
          {
            "code": {
              "text": "Diastolic blood pressure"
            },
            "valueQuantity": {
              "value": 72,
              "unit": "mmHg"
            }
          }
        ]
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-4",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-4",
        "status": "final",
        "code": {
          "text": "Heart rate"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueQuantity": {
          "value": 74,
          "unit": "beats/min"
        }
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-5",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-5",
        "status": "final",
        "code": {
          "text": "Temperature"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Afebrile"
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-6",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-6",
        "status": "final",
        "code": {
          "text": "Oxygen saturation"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueQuantity": {
          "value": 99,
          "unit": "%"
        },
        "note": [
          {
            "text": "On room air."
          }
        ]
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-7",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-7",
        "status": "final",
        "code": {
          "text": "Body mass index"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueQuantity": {
          "value": 27,
          "unit": "kg/m2"
        },
        "note": [
          {
            "text": "Approximate."
          }
        ]
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-8",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-8",
        "status": "final",
        "code": {
          "text": "Lumbar examination"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Mild tenderness of right lumbar paraspinal muscles; no midline tenderness. Slightly reduced flexion with pain, but able to move in all directions."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-9",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-9",
        "status": "final",
        "code": {
          "text": "Straight leg raise"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Negative on both sides."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-10",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-10",
        "status": "final",
        "code": {
          "text": "Lower limb neurological examination and gait"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Lower limb power, reflexes, and sensation grossly normal; gait normal."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-11",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-11",
        "status": "final",
        "code": {
          "text": "Daytime sleepiness"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Longstanding hypersomnolence. Patient says she could nap pretty much any time or anywhere. Partner reportedly says she nods off on the couch and at work; patient minimises the concern. Patient feels drowsy a lot, has zoned out at red lights, and denies actually falling asleep while driving. Partner, not present, is reportedly worried about her daytime sleepiness and driving."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-12",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-12",
        "status": "final",
        "code": {
          "text": "Sleep pattern and restorative quality"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Usually in bed around 10–11 pm and gets up around 6–6:30 am; wakes unrefreshed."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-13",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-13",
        "status": "final",
        "code": {
          "text": "Kicking during sleep"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Patient reports kicking in sleep; partner is disturbed by it."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-14",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-14",
        "status": "final",
        "code": {
          "text": "Sleep-related symptoms denied"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Per patient, partner reports no snoring or apnoeas. Patient denies cataplexy, sleep paralysis, and hallucinations."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-15",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-15",
        "status": "final",
        "code": {
          "text": "Mood and concentration symptoms"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Low motivation, fatigue, poor concentration, and feeling foggy. Denies current suicidal ideation."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/MedicationStatement/medication-statement-1",
      "resource": {
        "resourceType": "MedicationStatement",
        "id": "medication-statement-1",
        "status": "active",
        "medicationCodeableConcept": {
          "text": "Sertraline"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "dosage": [
          {
            "text": "50 mg mane; misses a few doses here and there",
            "timing": {
              "repeat": {
                "timeOfDay": [
                  "morning"
                ]
              }
            },
            "doseAndRate": [
              {
                "doseQuantity": {
                  "value": 50,
                  "unit": "mg"
                }
              }
            ]
          }
        ]
      }
    },
    {
      "fullUrl": "https://example.org/fhir/MedicationRequest/medication-request-1",
      "resource": {
        "resourceType": "MedicationRequest",
        "id": "medication-request-1",
        "status": "active",
        "intent": "order",
        "medicationCodeableConcept": {
          "text": "Paracetamol"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "dosageInstruction": [
          {
            "text": "1 g up to four times daily as needed, encouraged for short-term use if needed",
            "asNeededBoolean": true,
            "timing": {
              "repeat": {
                "frequency": 4,
                "period": 1,
                "periodUnit": "d"
              }
            },
            "doseAndRate": [
              {
                "doseQuantity": {
                  "value": 1,
                  "unit": "g"
                }
              }
            ]
          }
        ]
      }
    }
  ]
}

